INSERT INTO `ps_product_lang` VALUES (1000,1,1,'\" \"','','name','','','','name','','','',''),(1000,1,2,'ANGORA 100%\nKolor 01 biały<br />Skład:  angora 100%<br />Motek 10 gram  50 metrów<br />Zalecane druty numer 3-3,5<br />Próbka 10 na 10 cm to 27 oczek i 34 rzędy<br />Pranie ręczne.','','angora-100-01','','','','Angora 100% 01','','','',''),(1001,1,1,'\" \"','','name','','','','name','','','',''),(1001,1,2,'ANGORA 100%\nKolor 010  popielaty<br />Skład:  angora 100%<br />Motek 10 gram  50 metrów<br />Zalecane druty numer 3-3,5<br />Próbka 10 na 10 cm to 27 oczek i 34 rzędy<br />Pranie ręczne.','','angora-100-010','','','','Angora 100% 010','','','',''),(1002,1,1,'\" \"','','name','','','','name','','','',''),(1002,1,2,'ANGORA 100%\nKolor 3 - ecru/krem<br />Skład:  angora 100%<br />Motek 10 gram  50 metrów<br />Zalecane druty numer 3-3,5<br />Próbka 10 na 10 cm to 27 oczek i 34 rzędy<br />Pranie ręczne.','','angora-100-03','','','','Angora 100% 03','','','',''),(1003,1,1,'\" \"','','name','','','','name','','','',''),(1003,1,2,'RAFIA\n\nMożna użyć do szydełkowania lub robienia na drutach czapek, torebek letnich, podkładek i różnych dekoracji, ale także do układania lub wiązania kompozycji kwiatowych. Jest mocne i lekkie.\nWłókna pochodzą  z palm rodzaju Raphia.\n \nRozmiar szydełka: 5,5\n \nZ jednego motka można wykonać prostokąt 30 na 35 cm .\n\n\nszerokość taśmy: 5 - 8 mm\nNawój: 100 m\n\n\n\nKolor: butelkowa zieleń','','rafia---czerwona-08','','','','Rafia   czerwona 08','','','',''),(1004,1,1,'\" \"','','name','','','','name','','','',''),(1004,1,2,'RAFIA\n\nMożna użyć do szydełkowania lub robienia na drutach czapek, torebek letnich, podkładek i różnych dekoracji, ale także do układania lub wiązania kompozycji kwiatowych. Jest mocne i lekkie.\nWłókna pochodzą  z palm rodzaju Raphia.\n \nRozmiar szydełka: 5,5\n \nZ jednego motka można wykonać prostokąt 30 na 35 cm .\n\n\nszerokość taśmy: 5 - 8 mm\nNawój: 100 m\n\n\n\nKolor: butelkowa zieleń','','rafia---niebieska-07','','','','Rafia   niebieska 07','','','',''),(1005,1,1,'\" \"','','name','','','','name','','','',''),(1005,1,2,'RAFIA\n\nMożna użyć do szydełkowania lub robienia na drutach czapek, torebek letnich, podkładek i różnych dekoracji, ale także do układania lub wiązania kompozycji kwiatowych. Jest mocne i lekkie.\nWłókna pochodzą  z palm rodzaju Raphia.\n \nRozmiar szydełka: 5,5\n \nZ jednego motka można wykonać prostokąt 30 na 35 cm .\n\n\nszerokość taśmy: 5 - 8 mm\nNawój: 100 m\n\n\n\nKolor: butelkowa zieleń','','rafia---zielona-13','','','','Rafia   zielona 13','','','',''),(1006,1,1,'\" \"','','name','','','','name','','','',''),(1006,1,2,'RAFIA\n\nMożna użyć do szydełkowania lub robienia na drutach czapek, torebek letnich, podkładek i różnych dekoracji, ale także do układania lub wiązania kompozycji kwiatowych. Jest mocne i lekkie.\n\n \nRozmiar szydełka: 5,5\n \nZ jednego motka można wykonać prostokąt 30 na 35 cm .\n\n\nszerokość taśmy: 5 - 8 mm\nNawój: 80 - 100 m\nWaga 50 gramów\n\n\n\nKolor:','','rafia--ciemny-popiel','','','','Rafia  ciemny popiel','','','',''),(1007,1,1,'\" \"','','name','','','','name','','','',''),(1007,1,2,'RAFIA\n\nMożna użyć do szydełkowania lub robienia na drutach czapek, torebek letnich, podkładek i różnych dekoracji, ale także do układania lub wiązania kompozycji kwiatowych. Jest mocne i lekkie.\n\n \nRozmiar szydełka: 5,5\n \nZ jednego motka można wykonać prostokąt 30 na 35 cm .\n\n\nszerokość taśmy: 5 - 8 mm\nNawój: 80 - 100 m\nWaga 50 gramów\n\n\n\nKolor: kremowy','','rafia--krem','','','','Rafia  krem','','','',''),(1008,1,1,'\" \"','','name','','','','name','','','',''),(1008,1,2,'RAFIA\n \n\nRafia to znana od dawna ulubiona włóczka na letnie dzianiny: włóczka tasiemkowa wykonana z naturalnego włókna o półmatowym wyglądzie, wystarczająco miękka do robienia na drutach, która stanie się idealnym narzędziem do tworzenia toreb, czapek czy kapeluszy , a także podkładek pod talerze, koszyczków i drobnych akcesoriów do letniego wypo